<script setup>
import {ref,computed} from 'vue';import {useFood} from '../stores/food.js';import {useCart} from '../stores/cart.js';import FoodCard from '../components/FoodCard.vue';import {money} from '../composables/useTask.js'
const food=useFood(),cart=useCart(),search=ref(''),category=ref('All');const categories=computed(()=>['All',...new Set(food.foods.map(f=>f.category))]);const filtered=computed(()=>food.foods.filter(f=>(category.value==='All'||f.category===category.value)&&f.name.toLowerCase().includes(search.value.toLowerCase())))
</script><template><div class="hero"><div><small>FRESHLY PREPARED · EVERY DAY</small><h1>Good food.<br>Happy mood.</h1><p>Order your favourite meals in just a few clicks.</p></div><div class="heroart">🍕</div></div><div class="toolbar"><h2>Explore our menu</h2><input v-model="search" placeholder="Search food" aria-label="Search food"></div><div class="filters"><button v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c}}</button></div><div class="grid"><FoodCard v-for="f in filtered" :key="f.id" :food="f" @add="cart.change($event,1)"/></div><p v-if="!filtered.length">No food found.</p><div v-if="cart.count" class="cartbar"><b>{{cart.count}} items · {{money(cart.total)}}</b><RouterLink class="primary" to="/cart">View cart</RouterLink></div></template>
